  "emmy/ensemble_allocation_audit.py": """"Conditional saved-array arithmetic; no neural inference or device execution."""
import hashlib
import json
from pathlib import Path
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
paths = [ROOT / 'branches/branch-2/ada/conditional-latents.npz',
         ROOT / 'branches/branch-2/ada/conditional-latents-hydrogens.npz',
         ROOT / 'branches/branch-2/ada/checkpoint-results.json']
arrays = [np.load(p) for p in paths[:2]]
c = np.concatenate([a['norm_products'] for a in arrays], axis=1)
u = np.concatenate([a['predictions'] for a in arrays], axis=1)
rows = json.loads(paths[2].read_text())['rows']
rows = sorted(rows, key=lambda r: (r['replicate'], r['fold']))
assert [(r['replicate'], r['fold']) for r in rows] == [(r,f) for r in range(9) for f in range(5)]
b = np.array([r['bias'][0] for r in rows])[:, None, None]
v = c*c - (u-b)**2
assert c.shape == (45,12,120) and v.min() > 0

def quantiles(a):
    return np.quantile(a, [0,.05,.5,.95,1]).tolist()

# With total shots T per edge, uniform allocation variance is mean(v)/T.
# Continuous optimal allocation variance is mean(sqrt(v))**2/T.
robust_equal = np.mean(c*c, axis=0)
robust_opt = np.mean(c, axis=0)**2
var_equal = np.mean(v, axis=0)
var_opt = np.mean(np.sqrt(v), axis=0)**2
member_variance = np.var(u, axis=0, ddof=0)
assert np.all(member_variance > 0)
envelope = c.max(axis=1)
assert np.all(robust_equal >= robust_opt-1e-12)
assert np.all(var_equal >= var_opt-1e-12)

# Verify the cost-aware allocation with a declared synthetic cost schedule.
# This schedule is only an algebra check, not an estimated device cost.
k = np.linspace(1,3,45)[:,None,None]
budget = 1e6
score = c/np.sqrt(k)
shots = budget*score / np.sum(k*score, axis=0, keepdims=True)
lhs = np.sum(c*c/shots, axis=0)
rhs = np.sum(c*np.sqrt(k), axis=0)**2/budget
assert np.max(abs(np.sum(k*shots,axis=0)-budget)) < 1e-8
assert np.max(abs(lhs-rhs)) < 1e-9
out = {
    'scope': 'Conditional twelve substitute mapping arrays over all 45 restored models. No historical-input validation, planner run, physical accuracy, device timing or shot requirement.',
    'numpy_version': np.__version__,
    'shape_model_mapping_edge': list(c.shape),
    'quantile_order': [0,.05,.5,.95,1],
    'robust_norm_allocation_uniform_to_optimal_cost_ratio': quantiles(robust_equal/robust_opt),
    'oracle_variance_allocation_uniform_to_optimal_cost_ratio': quantiles(var_equal/var_opt),
    'optimal_worst_case_variance_coefficient': quantiles(robust_opt),
    'oracle_optimal_variance_coefficient': quantiles(var_opt),
    'oracle_optimal_quantum_to_exact_member_sampling_variance_coefficient_ratio': quantiles(var_opt/member_variance),
    'coordinates_oracle_optimal_quantum_coefficient_above_member_variance': int(np.sum(var_opt > member_variance)),
    'mapping_envelope_uniform_to_optimal_cost_ratio': quantiles(np.mean(envelope**2,axis=0)/np.mean(envelope,axis=0)**2),
    'mapping_envelope_optimal_variance_coefficient': quantiles(np.mean(envelope,axis=0)**2),
    'overlap_absolute_max': float(np.max(abs((u-b)/c))),
    'oracle_variance_min': float(v.min()),
    'synthetic_nonuniform_cost_algebra_max_error': float(np.max(abs(lhs-rhs))),
    'source_sha256': {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},
    'limitations': ['Continuous fixed allocation ignores integer and setup costs.',
                    'Oracle variance allocation requires exact overlaps or separately charged pilot estimates.',
                    'Mapping envelope bounds only the twelve tested candidates, not historical or all admissible inputs.',
                    'Independent unbiased shots and exact frozen functions; correlated or systematic device error is excluded.']
}
(ROOT/'emmy/ensemble-allocation-diagnostic.json').write_text(json.dumps(out,indent=2)+'\n')
print(json.dumps({k:v for k,v in out.items() if k not in ['source_sha256','limitations']},indent=2))
