import numpy as np
import pennylane as qml

ROOT = Path(__file__).resolve().parent
rng = np.random.default_rng(20261007)
d, q = 187, 8
x = np.pad(rng.uniform(.01, 1., d), (0, 256-d))
w = np.pad(rng.normal(size=d), (0, 256-d))
x /= np.linalg.norm(x)
w /= np.linalg.norm(w)
wires = list(range(1, q+1))
primitive = {'RX', 'RY', 'RZ', 'PhaseShift', 'Hadamard', 'PauliX', 'PauliZ', 'CNOT', 'GlobalPhase'}

def flatten(op, depth=0):
    if op.name in primitive:
        return [op]
    if depth > 30:
        raise RuntimeError('decomposition recursion: '+op.name)
    return [g for child in op.decomposition() for g in flatten(child, depth+1)]

def prep(v):
    return qml.MottonenStatePreparation(v, wires=wires).decomposition()

px, pw = prep(x), prep(w)
counts = {}
circuits = {
    # P routing: prepare input then compare with the controlled preparation.
    'P_routing_arbitrary_frozen_row': px + [qml.Hadamard(0)]
        + [qml.ctrl(qml.adjoint(op), control=0) for op in reversed(px)]
        + [qml.ctrl(op, control=0) for op in pw] + [qml.Hadamard(0)],
    # Equivalent real overlap: start in zero and measure U_x dagger U_w.
    'zero_start_arbitrary_frozen_row': [qml.Hadamard(0)]
        + [qml.ctrl(op, control=0) for op in pw]
        + [qml.ctrl(qml.adjoint(op), control=0) for op in reversed(px)]
        + [qml.Hadamard(0)],
}
theta = rng.uniform(0., 2*np.pi, (3, q, 3))
ansatz = qml.StronglyEntanglingLayers(theta, wires=wires).decomposition()
circuits['P_routing_restricted_three_layer_row'] = px + [qml.Hadamard(0)] \
    + [qml.ctrl(qml.adjoint(op), control=0) for op in reversed(px)] \
    + [qml.ctrl(op, control=0) for op in ansatz] + [qml.Hadamard(0)]

